import 'package:flutter_local_notifications/flutter_local_notifications.dart';
import 'package:timezone/data/latest.dart' as tz; import 'package:timezone/timezone.dart' as tz;
class NotificationService {final _plugin=FlutterLocalNotificationsPlugin();Future<void> init() async {tz.initializeTimeZones();const a=AndroidInitializationSettings('@mipmap/ic_launcher');await _plugin.initialize(const InitializationSettings(android:a,iOS:DarwinInitializationSettings()));}Future<void> scheduleDaily({int hour=7,int minute=0}) async {final now=tz.TZDateTime.now(tz.local);var next=tz.TZDateTime(tz.local,now.year,now.month,now.day,hour,minute);if(!next.isAfter(now))next=next.add(const Duration(days:1));await _plugin.zonedSchedule(100,'Your Qur’an journey awaits 🌙','Take a few minutes to read, revise and memorize.',next, const NotificationDetails(android:AndroidNotificationDetails('hifz_daily','Daily Qur’an',channelDescription:'Daily Qur’an reading and memorization reminder',importance:Importance.defaultImportance,priority:Priority.defaultPriority),iOS:DarwinNotificationDetails()),androidScheduleMode:AndroidScheduleMode.inexactAllowWhileIdle,matchesDateTimeComponents:DateTimeComponents.time);}}
